data "archive_file" "lambda_zip" {
  type        = "zip"
  source_file = "templates/lambda_handler.py"
  output_path = "lambda_function_payload.zip"
}

data "aws_ami" "amazon_linux_2" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "architecture"
    values = ["x86_64"]
  }

  filter {
    name   = "virtualization-type"
    values = ["hvm"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }

  filter {
    name   = "ena-support"
    values = ["true"]
  }

  owners = ["amazon"]
}

# This is a Terraform file that creates three resources:
# 1. An AWS DynamoDB Table
# 2. An AWS DynamoDB Entry (for the Access ID)
# 3. An AWS DynamoDB Entry (for the Secret Key)

resource "aws_dynamodb_table" "secrets_table" {
  name         = "secrets-table-${local.cgid_suffix}"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "key"

  attribute {
    name = "key"
    type = "S"
  }

  # Enable server-side encryption using the default AWS KMS key
  server_side_encryption {
    enabled = true
  }

  tags = {
    Name = "secrets_table"
  }
}

resource "aws_dynamodb_table_item" "access_key_id" {
  table_name = aws_dynamodb_table.secrets_table.name
  hash_key   = aws_dynamodb_table.secrets_table.hash_key

  item = jsonencode({
    key = {
      S = "secrets_manager_user_key_id"
    }
    value = {
      S = aws_iam_access_key.secrets_manager_user_key.id
    }
  })
}

resource "aws_dynamodb_table_item" "secret_access_key" {
  table_name = aws_dynamodb_table.secrets_table.name
  hash_key   = aws_dynamodb_table.secrets_table.hash_key

  item = jsonencode({
    key = {
      S = "secrets_manager_user_key_secret"
    }
    value = {
      S = aws_iam_access_key.secrets_manager_user_key.secret
    }
  })
}

# This is a Terraform file that creates several AWS EC2 resources:
# 1. A Data Source for an AWS Amazon Machine Image.
# 2. A TLS Private Key Resource
# 3. An AWS Key Pair Resource
# 4. An AWS Instance Resource
# 5. An AWS Security Group Resource

resource "tls_private_key" "id_rsa" {
  algorithm = "RSA"
  rsa_bits  = 2048
}

resource "aws_key_pair" "id_rsa" {
  key_name   = "idrsa-keypair"
  public_key = tls_private_key.id_rsa.public_key_openssh
}

resource "aws_instance" "web_app" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t3.micro"
  key_name      = aws_key_pair.id_rsa.key_name
  subnet_id     = aws_subnet.subnet.id

  vpc_security_group_ids = [
    aws_security_group.web_app_sg.id,
  ]

  user_data = base64encode(templatefile("templates/user_data.tpl", {
    aws_access_key_id     = aws_iam_access_key.secrets_manager_user_key.id,
    aws_secret_access_key = aws_iam_access_key.secrets_manager_user_key.secret,
    private_key           = tls_private_key.id_rsa.private_key_pem,
  }))

  # This sets the EC2 instance's IAM instance profile to the Dynamo DB profile created in iam.tf
  iam_instance_profile = aws_iam_instance_profile.dynamodb_instance_profile.name

  metadata_options {
    http_tokens   = "required"
    http_endpoint = "enabled"
  }

  tags = {
    Name = "CloudGoat Secrets in the Cloud Web App"
  }
}

resource "aws_security_group" "web_app_sg" {
  name        = "web_app_sg-${var.cgid}"
  description = "Allow inbound traffic to the web app and Vault"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  ingress {
    from_port   = 8200
    to_port     = 8200
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = var.cg_whitelist
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1" # -1 means all protocols
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# This Terraform file creates several resources for AWS Identity and Access Management (IAM):
# - An IAM User 
# - An IAM Access Key 
#
#   For AWS Simple Storage Service (S3):
#     - An IAM Policy 
#     - An IAM User Policy Attachment 
#
#   For AWS Lambda:
#     - An IAM Policy 
#     - An IAM User Policy Attachment 
#     - An IAM Role Policy
#
#   For AWS DynamoDB:
#     - An IAM Policy 
#     - An IAM Role
#     - An IAM Role Policy Attachment
#     - An IAM Instance Profile
#
#   For AWS Secrets Manager:
#     - An IAM User
#     - An IAM Access Key
#     - An IAM Role
#     - An IAM User Policy

resource "aws_iam_user" "low_priv_user" {
  name = "low-priv-user-${var.cgid}"
}

resource "aws_iam_access_key" "low_priv_user_key" {
  user = aws_iam_user.low_priv_user.name
}

resource "aws_iam_policy" "low_priv_user_s3_policy" {
  name        = "low_priv_user_s3_policy-${var.cgid}"
  description = "Policy to allow low_priv_user to list and read objects in the S3 bucket created by the scenario and list their user policies and policy attachments"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "s3:ListAllMyBuckets"
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = "s3:ListBucket"
        Effect   = "Allow"
        Resource = aws_s3_bucket.secrets_bucket.arn
      },
      {
        Action   = "s3:GetObject"
        Effect   = "Allow"
        Resource = "${aws_s3_bucket.secrets_bucket.arn}/*"
      },
      {
        Action = [
          "iam:ListUserPolicies",
          "iam:GetUserPolicy",
          "iam:ListAttachedUserPolicies"
        ]
        Effect   = "Allow"
        Resource = aws_iam_user.low_priv_user.arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "low_priv_user_s3_attachment" {
  user       = aws_iam_user.low_priv_user.name
  policy_arn = aws_iam_policy.low_priv_user_s3_policy.arn
}

resource "aws_iam_policy" "low_priv_user_lambda_policy" {
  name        = "low_priv_user_lambda_policy-${var.cgid}"
  description = "Policy to allow low_priv_user to enumerate and invoke the Lambda function"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action   = "lambda:ListFunctions"
        Effect   = "Allow"
        Resource = "*"
      },
      {
        Action   = "lambda:InvokeFunction"
        Effect   = "Allow"
        Resource = aws_lambda_function.this.arn
      }
    ]
  })
}

resource "aws_iam_user_policy_attachment" "low_priv_user_lambda_attachment" {
  user       = aws_iam_user.low_priv_user.name
  policy_arn = aws_iam_policy.low_priv_user_lambda_policy.arn
}


resource "aws_iam_user" "secrets_manager_user" {
  name = "${var.cgid}-secrets-manager-user"
}

resource "aws_iam_access_key" "secrets_manager_user_key" {
  user = aws_iam_user.secrets_manager_user.name
}

resource "aws_iam_user_policy" "secrets_manager_user_policy" {
  name = "secrets-manager-policy-${var.cgid}"
  user = aws_iam_user.secrets_manager_user.name

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "secretsmanager:ListSecrets",
          "secretsmanager:DescribeSecret",
          "secretsmanager:GetSecretValue"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}


# Is this even used?
resource "aws_iam_role" "secrets_manager_role" {
  name = "secrets-manager-role-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          AWS = aws_iam_role.lambda_execution.arn
        }
      }
    ]
  })
}


resource "aws_iam_role" "dynamodb_role" {
  name = "DavesDancingDoolittle-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "dynamodb_policy" {
  name = "dynamodb-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = "dynamodb:*"
        Resource = aws_dynamodb_table.secrets_table.arn
      },
      {
        Effect   = "Allow"
        Action   = "dynamodb:ListTables"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "dynamodb_policy_attachment" {
  name       = "dynamodb-policy-attachment"
  roles      = [aws_iam_role.dynamodb_role.id]
  policy_arn = aws_iam_policy.dynamodb_policy.arn
}

resource "aws_iam_instance_profile" "dynamodb_instance_profile" {
  name = "dynamodb-instance-profile"
  role = aws_iam_role.dynamodb_role.name
}

# This Terraform file creates the following AWS Lambda Resources:
# - An AWS Lambda Resource
# - An AWS IAM Role
# - An AWS IAM Role Policy

resource "aws_cloudwatch_log_group" "lambda" {
  name              = "/aws/lambda/cloudgoat-secrets-lambda-${var.cgid}"
  retention_in_days = 1
  skip_destroy      = false
}

resource "aws_lambda_function" "this" {
  function_name = "cloudgoat-secrets-lambda-${var.cgid}"

  filename         = data.archive_file.lambda_zip.output_path
  source_code_hash = data.archive_file.lambda_zip.output_base64sha256

  runtime = "python3.13"

  role    = aws_iam_role.lambda_execution.arn
  handler = "lambda_function.lambda_handler"

  logging_config {
    log_format = "JSON"
    log_group  = aws_cloudwatch_log_group.lambda.name
  }

  environment {
    variables = {
      API_KEY = "DavidsDelightfulDonuts2023"
    }
  }
}

resource "aws_iam_role" "lambda_execution" {
  name = "lambda_execution_role-${var.cgid}"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy" "lambda_policy" {
  name = "lambda-policy-${var.cgid}"
  role = aws_iam_role.lambda_execution.id

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "${aws_cloudwatch_log_group.lambda.arn}:log-stream:*"
      }
    ]
  })
}

locals {
  # Ensure the suffix doesn't contain invalid characters
  # Resources names can consist only of lowercase letters, numbers, dots (.), and hyphens (-).
  # https://docs.aws.amazon.com/AmazonS3/latest/userguide/bucketnamingrules.html
  cgid_suffix = replace(var.cgid, "/[^a-z0-9-.]/", "-")
}

# This Terraform file creates output values to expose information 
# about the infrastructure:
# - A Low-Privilege Access Key
# - A Low-Privilege Secret Key

output "low_priv_access_key" {
  value       = aws_iam_access_key.low_priv_user_key.id
  description = "Access key ID for the low privilege IAM user."
}

output "low_priv_secret_key" {
  value       = aws_iam_access_key.low_priv_user_key.secret
  description = "Secret access key for the low privilege IAM user."
  sensitive   = true
}

terraform {
  required_version = ">= 1.5"

  required_providers {
    archive = {
      source  = "hashicorp/archive"
      version = ">= 2.7.0"
    }

    aws = {
      source  = "hashicorp/aws"
      version = ">= 5.0.0"
    }

    tls = {
      source  = "hashicorp/tls"
      version = ">= 4.0.0"
    }
  }
}

provider "aws" {
  profile = var.profile
  region  = var.region

  default_tags {
    tags = {
      Stack    = var.stack-name
      Scenario = var.scenario-name
    }
  }
}

provider "tls" {}

# This Terraform file creates the following AWS Simple Storage Service Resources:
# - An AWS S3 Bucket 
# - An AWS S3 Object

resource "aws_s3_bucket" "secrets_bucket" {
  bucket        = "cg-secrets-bucket-${local.cgid_suffix}"
  force_destroy = true
  tags = {
    Description = "CloudGoat ${var.cgid} S3 Bucket used for storing seekz."
  }
}

resource "aws_s3_object" "web_app_url" {
  bucket  = aws_s3_bucket.secrets_bucket.id
  key     = "nates_web_app_url.txt"
  content = "http://${aws_instance.web_app.public_ip}:8080"
}

# This Terraform file creates the following resources for the AWS Secret's Manager:
# - A variable containing a regular expression for the secrets suffix.
# - An AWS Secret Manager Secret
# - An AWS Secret Manager Secret Version
# - An AWS Secret Manager Secret Policy

resource "aws_secretsmanager_secret" "this" {
  name        = "cg-secret-${local.cgid_suffix}"
  description = "A secret for CloudGoat scenario"
}

resource "aws_secretsmanager_secret_version" "this" {
  secret_id = aws_secretsmanager_secret.this.id
  secret_string = jsonencode({
    super_key                          = "JohnsJuicyJam"
    mega_secret                        = "BensBubblyBacon"
    ultra_mega_secret                  = "BenjaminsBlazingBungee"
    RyansRambunctiousRhinocerosRampage = "Congrats, you have successfully completed Secrets in the Cloud!"
  })
}

resource "aws_secretsmanager_secret_policy" "this" {
  secret_arn = aws_secretsmanager_secret.this.arn
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action    = "secretsmanager:GetSecretValue"
        Effect    = "Allow"
        Resource  = aws_secretsmanager_secret.this.arn
        Principal = "*"
      }
    ]
  })
}

variable "profile" {
  description = "The AWS profile to use when deploying resources"
  type        = string
}

variable "region" {
  description = "The AWS region to deploy resources into"
  default     = "us-east-1"
  type        = string
}

variable "cgid" {
  description = "CGID variable for unique naming between scenarios"
  type        = string
}

variable "cg_whitelist" {
  description = "User's public IP address(es)"
  type        = list(string)
}

variable "stack-name" {
  description = "Name of the stack"
  default     = "CloudGoat"
  type        = string
}

variable "scenario-name" {
  description = "Name of the scenario being deployed"
  default     = "scenario_template"
  type        = string
}

resource "aws_vpc" "vpc" {
  cidr_block = "10.0.0.0/16"
  tags = {
    Name = "cg-vpc-${var.cgid}"
  }
}

resource "aws_internet_gateway" "igw" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "cg-igw-${var.cgid}"
  }
}

resource "aws_subnet" "subnet" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a" # or dynamically get a random availability zone
  map_public_ip_on_launch = true
  tags = {
    Name = "cg-subnet-${var.cgid}"
  }
}

resource "aws_route_table" "route_table" {
  vpc_id = aws_vpc.vpc.id
  tags = {
    Name = "cg-route-table-${var.cgid}"
  }
}

resource "aws_route" "route" {
  route_table_id         = aws_route_table.route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.igw.id
}

resource "aws_route_table_association" "route_table_association" {
  subnet_id      = aws_subnet.subnet.id
  route_table_id = aws_route_table.route_table.id
}
